// Working with recipes
RecipeManager manager = level.getRecipeManager();

// Get recipe
Optional<ShapedRecipe> recipe = manager.getRecipeFor(
    RecipeType.CRAFTING,
    craftingContainer,
    level
);

// Get all recipes of type
List<ShapedRecipe> shapedRecipes = level.getRecipeManager()
    .getAllRecipesFor(RecipeType.CRAFTING)
    .stream()
    .filter(r -> r instanceof ShapedRecipe)
    .map(r -> (ShapedRecipe) r)
    .collect(Collectors.toList());
